from lib import *

B1 = lesson('1강. 한 줄 표현 — 컴프리헨션·map·filter·zip 을 자유자재로', 40,
'- 컴프리헨션: `[식 for x in 대상 if 조건]` — **거르는 if 는 뒤**, **값을 고르는 if-else 는 앞**\n- 중첩: `[… for a in A for b in B]` 는 바깥 for 가 먼저 (왼쪽이 바깥)\n- `map(함수, 대상)`, `filter(함수, 대상)` 은 **list() 로 감싸야** 리스트\n- `lambda x: 식` 은 이름 없는 한 줄 함수\n- `zip` 은 짧은 쪽에 맞춰 묶고, `enumerate(대상, start)` 는 (번호, 값)\n- 딕셔너리·집합 컴프리헨션: `{k: v for …}`, `{식 for …}`',
explain('마스터의 스킬 [β] 사용법',
  [T('**마스터의 스킬 [β]** 는 1학년 1학기 **2차 고사**의 응용편이에요. L.O.T.C. [β] 에서 배운 함수·딕셔너리·재귀·탐색·정렬을 **시험에서 점수가 갈리는 지점** 중심으로 깊게 팝니다.'),
   flip(['2차 고사의 큰 문제', '메뉴형 프로그램(함수 5개, list of dict) 15~20점'], ['2026 새 유형', '이진 탐색의 문제점 서술 · 재귀 호출 횟수 · 합병 정렬 빈칸'], ['매년 나오는 소형 문항', '한 줄 표현(컴프·map·filter·zip) · 문자열 메서드 · set 연산'], ['감점 1순위', '반환값 None · 가변 기본값 · 전역 변수 · 경계 조건'])],
  [T('강마다 **복습 → 함정 해부 → 기출·심화 문제** 순서예요. 실습 제목의 **[기출유사]** 는 실제 시험과 같은 구조, **[심화]** 는 한 단계 위예요.'),
   exam('2025 2차는 메뉴의 틀을 주고 **함수의 몸통만 쓰게** 했어요. 그래서 이 코스의 실습도 "입력 → 함수 → 출력"의 흐름을 스스로 세우는 연습을 많이 해요.')]),
review('🔁 L.O.T.C. [β] 핵심 점검', [T('시작하기 전에 기본기를 확인해요.'), flip(['[x * 2 for x in a]', 'a 의 각 원소를 2배 한 새 리스트'], ['"a,b".split(",")', '["a", "b"]'], ['d.get(k, 0)', '키가 없으면 0'], ['def f(): pass 의 반환값', 'None'], ['{1, 2} | {2, 3}', '{1, 2, 3}'], ['재귀 함수에 꼭 필요한 것', '종료 조건(기저 사례)'])]),
outq('점검 — 출력 결과는?', 'a = [3, 8, 5]\nb = [x for x in a if x > 4]\nc = list(map(str, a))\nprint(b, "-".join(c), sum(b) // len(b))', review=True),
explain('컴프리헨션의 문법 지도',
  [T('컴프리헨션은 "빈 리스트 + for + append"를 한 줄로 줄인 거예요. 시험은 **두 형태를 서로 바꾸는** 문제로 나와요(2025 1번, 12점).'),
   cmp('풀어 쓴 코드', 'out = []\nfor x in range(6):\n    if x % 2 == 0:\n        out.append(x * x)\nprint(out)', '컴프리헨션', 'out = [x * x for x in range(6) if x % 2 == 0]\nprint(out)', tones=('', 'good')),
   key('읽는 순서: **for → if → 맨 앞의 식**. 쓰는 순서는 `[식 for … if …]`.')],
  [T('`if` 가 두 군데에 올 수 있어요. 뜻이 완전히 달라요.'),
   tabs(['뒤의 if — 거르기', '조건에 맞는 것만 **남겨요**. 개수가 줄어요.', 'a = [1, 2, 3, 4]\nprint([x for x in a if x % 2 == 0])'], ['앞의 if-else — 고르기', '모든 원소를 **바꿔요**. 개수는 그대로. `else` 가 반드시 필요해요.', 'a = [1, 2, 3, 4]\nprint(["짝" if x % 2 == 0 else "홀" for x in a])'], ['둘 다', '거른 뒤 바꾸기', 'a = [1, 2, 3, 4, 5, 6]\nprint([x * 10 if x > 4 else x for x in a if x % 2 == 0])']),
   warn('`[x if x > 0 for x in a]` 는 **SyntaxError** 예요. 앞에 쓰는 if 에는 else 가 꼭 있어야 해요. 거르려면 뒤에 쓰세요.')],
  [T('for 가 두 개면 **왼쪽이 바깥** 반복이에요.'),
   trace('out = [(a, b) for a in range(2) for b in "xy"]\nprint(out)\ngrid = [[r * 3 + c for c in range(3)] for r in range(2)]\nprint(grid)', '이중 for 와 2차원 리스트 만들기'),
   key('`[[…] for r in …]` 처럼 **안쪽에 대괄호**가 또 있으면 2차원 리스트, 대괄호 하나에 for 두 개면 한 줄로 펼친 1차원 리스트예요.')]),
outq('[기출유사] 출력 결과는?', 'w = ["apple", "kiwi", "banana", "fig"]\nprint([len(x) for x in w])\nprint([x.upper() for x in w if len(x) <= 4])\nprint([x[0] if len(x) > 4 else x for x in w])'),
outq('[심화] 출력 결과는?', 'print([a * b for a in range(1, 4) for b in range(a, 4) if (a + b) % 2 == 0])\nprint([[j for j in range(i)] for i in range(1, 4)])'),
spot('[기출유사] 한 줄 표현 중 **SyntaxError 가 나는 줄**은?', 'a = [5, -2, 7, -9]\nb = [x for x in a if x > 0]\nc = [x if x > 0 else 0 for x in a]\nd = [x if x > 0 for x in a]\ne = [abs(x) for x in a]', 4, '앞에 쓰는 if 는 else 와 짝이어야 해요. 거르는 뜻이면 `[x for x in a if x > 0]`.'),
explain('map · filter · lambda — 같은 일을 다른 문법으로',
  [T('"**map 과 filter 를 반드시 사용**"(2024 로또 문제) 같은 제약이 붙어요. 컴프리헨션과 **서로 변환**할 수 있어야 해요.'),
   tabs(['map', '모든 원소에 함수를 적용', 'a = ["3", "1", "2"]\nprint(list(map(int, a)))\nprint([int(x) for x in a])'], ['filter', '함수가 참인 것만 남김', 'a = [5, -2, 7, -9]\nprint(list(filter(lambda x: x > 0, a)))\nprint([x for x in a if x > 0])'], ['map + lambda', '식을 직접 쓰고 싶을 때', 'a = [1, 2, 3]\nprint(list(map(lambda x: x * x, a)))\nprint([x * x for x in a])'], ['filter 뒤 map', '거른 뒤 바꾸기 — **안쪽이 먼저**', 'a = [1, 2, 3, 4]\nprint(list(map(lambda x: x * 10, filter(lambda x: x % 2 == 0, a))))\nprint([x * 10 for x in a if x % 2 == 0])']),
   key('`map(f, a)` ↔ `[f(x) for x in a]`, `filter(f, a)` ↔ `[x for x in a if f(x)]`')],
  [T('map 과 filter 의 결과는 리스트가 **아니에요**. 한 번 쓰면 비어 버리는 "일회용"이에요.'),
   C('m = map(int, ["1", "2", "3"])\nprint(type(m).__name__)\nprint(sum(m))\nprint(sum(m))      # 이미 다 써서 0\nprint(list(map(len, ["ab", "c"])))'),
   warn('`print(map(int, a))` 는 `<map object …>` 를 출력해요. 내용을 보려면 `list()` 로 감싸거나 `print(*map(…))` 을 써요. 그리고 **두 번 쓰려면 리스트로 저장**해야 해요.')],
  [T('`lambda` 는 `def` 를 한 줄로 줄인 **이름 없는 함수**예요. 매개변수가 여러 개여도 돼요.'),
   cmp('def', 'def add(a, b):\n    return a + b\nprint(add(2, 3))', 'lambda', 'add = lambda a, b: a + b\nprint(add(2, 3))', tones=('', '')),
   C('pairs = [("민", 80), ("솔", 95), ("준", 70)]\nprint(sorted(pairs, key=lambda p: p[1], reverse=True))\nprint(max(pairs, key=lambda p: p[1])[0])\nprint(list(map(lambda a, b: a * b, [1, 2, 3], [4, 5, 6])))', 'key= 에 쓰는 lambda, 두 리스트를 동시에 map')]),
match('같은 결과를 내는 표현끼리 이어 보세요. (`a = [1, 2, 3, 4]`)', [['list(map(lambda x: x + 1, a))', '[x + 1 for x in a]'], ['list(filter(lambda x: x > 2, a))', '[x for x in a if x > 2]'], ['list(map(str, a))', '[str(x) for x in a]'], ['sum(map(lambda x: x % 2, a))', 'len([x for x in a if x % 2 == 1])'], ['list(filter(None, [0, 1, "", "a"]))', '[1, "a"]']], '`filter(None, …)` 은 참 같은 값만 남겨요.'),
fill('[기출유사] 문자열 리스트에서 **길이가 3 이상인 것만** 골라 **대문자**로 바꿔요. map 과 filter 를 모두 사용해요.', 'w = ["go", "python", "c", "java"]\nr = list(___(lambda s: s.upper(), ___(lambda s: len(s) >= 3, w)))\nprint(r)', ['map', 'filter'], expect="['PYTHON', 'JAVA']"),
outq('[심화] 출력 결과는?', 'nums = [4, 9, 16]\nf = lambda x, k=2: x ** (1 / k)\nm = map(f, nums)\nfirst = next(m)\nprint(first, list(map(int, m)))\nprint(list(map(lambda a, b: a - b, nums, nums[1:])))', '`next(m)` 이 첫 값을 꺼내 가서 남은 것은 두 개예요. 두 리스트를 함께 map 하면 **짧은 쪽**에 맞춰요.'),
explain('zip · enumerate · 딕셔너리 컴프리헨션',
  [T('`zip` 은 여러 리스트를 **같은 위치끼리** 묶어요. 2023 행렬 덧셈(9점)이 zip + 컴프리헨션이었어요.'),
   trace('A = [[1, 2], [3, 4]]\nB = [[10, 20], [30, 40]]\nC = [[x + y for x, y in zip(ra, rb)] for ra, rb in zip(A, B)]\nprint(C)', '바깥 zip 은 행끼리, 안쪽 zip 은 원소끼리'),
   warn('길이가 다르면 **짧은 쪽**에서 멈춰요. 오류가 나지 않아서 데이터가 조용히 잘려요.')],
  [T('`enumerate` 는 번호를 붙여 줘요. 2026 5번은 `enumerate(…, start=1)` + `zip` + `set` 이었어요.'),
   C('names = ["민", "솔", "준"]\nscores = [80, 95, 70]\nfor i, (n, s) in enumerate(zip(names, scores), start=1):\n    print(i, n, s)\nprint(dict(zip(names, scores)))\nprint([i for i, s in enumerate(scores) if s >= 80])'),
   key('`for i, (n, s) in enumerate(zip(…))` — zip 이 만든 쌍을 **괄호로** 받아야 해요. `dict(zip(키들, 값들))` 은 두 리스트로 딕셔너리를 만드는 관용구예요.')],
  [T('중괄호를 쓰면 **딕셔너리·집합** 컴프리헨션이 돼요.'),
   C('names = ["민", "솔", "준"]\nscores = [80, 95, 70]\nd = {n: s for n, s in zip(names, scores)}\nprint(d)\nprint({n: s for n, s in d.items() if s >= 80})\nprint({s // 10 * 10 for s in scores + [85, 91]})\nprint({v: k for k, v in d.items()})', '거르기, 중복 제거, 키·값 뒤집기')]),
outq('[기출유사] 출력 결과는?', 'a = [3, 1, 4]\nb = "xyz!"\nprint(list(zip(a, b)))\nprint([c * n for n, c in zip(a, b)])\nprint({c: i for i, c in enumerate(b, 1) if i % 2})'),
sh('[기출유사] `list(zip([1, 2, 3], "ab", [True]))` 의 **길이**는?', 1, '가장 짧은 `[True]` 에 맞춰 한 묶음만 만들어져요.'),
essay('[기출유사] `m = map(int, ["1", "2", "3"])` 뒤에 `print(max(m))` 과 `print(min(m))` 을 차례로 실행하면 두 번째에서 오류가 나요. **이유**를 서술하고 **고치는 방법**을 쓰세요.', 'map 의 결과는 리스트가 아니라 값을 하나씩 꺼내 쓰는 일회용 객체(이터레이터)이다. max(m) 이 값을 모두 꺼내 쓰면 m 에는 남은 값이 없으므로, min(m) 은 빈 대상에서 최솟값을 구하려다 ValueError 가 발생한다. m = list(map(int, …)) 처럼 리스트로 바꿔 저장하면 여러 번 사용할 수 있다.', ['map 의 결과가 리스트가 아니라 한 번만 쓸 수 있는 객체라고 썼다', 'max 가 값을 다 꺼내 써서 비었다고 썼다', '빈 대상이라 오류(ValueError)가 난다고 썼다', 'list() 로 바꿔 저장한다고 썼다']),
prac('[기출유사] 한 줄 변환 4종', '정수들이 한 줄에 주어져요. 다음 네 가지를 한 줄씩 출력하세요(리스트는 공백으로 구분, 비어 있으면 `없음`).\n\n1. 모든 수를 **제곱**한 리스트\n2. **짝수만** 고른 리스트\n3. 3의 배수는 `Fizz`, 아니면 그 수 그대로\n4. 이웃한 두 수의 **차**(뒤 - 앞)의 리스트 (수가 하나면 `없음`)\n\n[조건] ○ 1번은 `map` + `lambda`, 2번은 `filter`, 3번은 조건식이 들어간 컴프리헨션, 4번은 `zip` 을 사용할 것',
  'a = list(map(int, input().split()))\nr1 = list(map(lambda x: x * x, a))\nr2 = list(filter(lambda x: x % 2 == 0, a))\nr3 = ["Fizz" if x % 3 == 0 else x for x in a]\nr4 = [y - x for x, y in zip(a, a[1:])]\nfor r in [r1, r2, r3, r4]:\n    if r:\n        print(*r)\n    else:\n        print("없음")',
  ['3 8 5 12', '7', '1 5 7', '0 -3 6 -4', '2 4 6 8 10', '9 9 9'],
  hints=['이웃한 쌍: `zip(a, a[1:])`', '`"Fizz" if x % 3 == 0 else x` — 앞에 쓰는 if 는 else 가 필요해요.', '빈 리스트는 `if r:` 로 검사해요.']),
prac('[기출유사] 행렬 계산기', '크기가 같은 두 행렬 A, B 가 주어져요. A + B 와, A 의 **전치 행렬**(행과 열을 바꾼 행렬)을 출력하세요.\n\n입력: 첫 줄 `r c`, 이어서 r줄에 A, r줄에 B (1 ≤ r, c ≤ 10)\n\n출력: A + B 를 r줄에, 빈 줄 없이 이어서 A 의 전치 행렬을 c줄에 출력. 마지막 줄에 A + B 에서 **각 행의 최댓값들의 합**.\n\n[조건] ○ 덧셈은 `zip` 과 컴프리헨션으로 구현할 것',
  'r, c = map(int, input().split())\nA = [list(map(int, input().split())) for _ in range(r)]\nB = [list(map(int, input().split())) for _ in range(r)]\nS = [[x + y for x, y in zip(ra, rb)] for ra, rb in zip(A, B)]\nfor row in S:\n    print(*row)\nT = [[A[i][j] for i in range(r)] for j in range(c)]\nfor row in T:\n    print(*row)\nprint(sum(max(row) for row in S))',
  ['2 3\n1 2 3\n4 5 6\n10 20 30\n40 50 60', '1 1\n5\n-5', '3 2\n1 2\n3 4\n5 6\n0 0\n0 0\n0 0', '2 2\n1 0\n0 1\n1 1\n1 1', '1 4\n4 3 2 1\n1 2 3 4', '3 1\n7\n8\n9\n1\n1\n1'],
  hints=['행렬 읽기: `[list(map(int, input().split())) for _ in range(r)]`', '덧셈: 바깥 zip 으로 행끼리, 안쪽 zip 으로 원소끼리', '전치: `[[A[i][j] for i in range(r)] for j in range(c)]` — 바깥이 열 번호예요.']),
prac('[심화] 성적표 파이프라인', '학생들의 `이름:점수` 가 공백으로 구분되어 한 줄에 주어져요(점수는 0~100, 이름은 중복 없음).\n\n1. 점수가 60 이상인 학생만 남기고(합격자)\n2. 합격자를 **점수 내림차순**(같으면 입력 순)으로 정렬해\n3. `순위. 이름(점수)` 를 한 줄씩 출력 — 순위는 1부터 차례로\n4. 마지막 줄에 합격자의 이름을 가나다(사전)순으로 `, ` 로 이어 출력\n\n합격자가 없으면 `합격자 없음` 만 출력해요.\n\n[조건] ○ 반복문(for/while **문**)을 쓰지 말고 컴프리헨션·`map`·`filter`·`sorted`·`enumerate`·`join` 으로만 해결할 것 (출력은 `print("\\n".join(…))` 활용)',
  'data = [p.split(":") for p in input().split()]\npassed = sorted(filter(lambda p: int(p[1]) >= 60, data), key=lambda p: -int(p[1]))\nif passed:\n    print("\\n".join(f"{i}. {n}({s})" for i, (n, s) in enumerate(passed, 1)))\n    print(", ".join(sorted(n for n, s in passed)))\nelse:\n    print("합격자 없음")',
  ['민:80 솔:95 준:55 하:80', '가:59 나:0', '다:60', '라:100 마:100 가:100', 'z:61 y:62 x:63 w:10', '하나:70 둘:90 셋:70 넷:90 다섯:59'],
  hints=['`p.split(":")` 로 [이름, 점수] 쌍을 만들어요.', '`sorted(…, key=lambda p: -int(p[1]))` — 정렬은 안정적이라 동점은 입력 순서가 유지돼요.', '`"\\n".join(f"{i}. {n}({s})" for i, (n, s) in enumerate(passed, 1))`'], ex='`sorted` 는 **안정 정렬**이라 key 가 같은 원소의 순서를 바꾸지 않아요. 그래서 "같으면 입력 순"이 자동으로 지켜져요.'),
)

B2 = lesson('2강. 문자열 가공 — split·join 과 형식 검사', 40,
'- `split()` 은 공백 여러 개를 하나로 보고, `split(",")` 는 **빈 문자열도** 조각으로 만든다\n- `"구분자".join(문자열 리스트)` — 숫자 리스트는 `map(str, …)` 을 거쳐야 한다\n- `strip()` 은 **양 끝**만, `replace(a, b)` 는 전부\n- `find` 는 없으면 -1, `count` 는 겹치지 않게 센다\n- 검사 메서드: `isdigit` `isalpha` `isalnum` `isupper` `islower` — 빈 문자열은 모두 False\n- 형식 검사 순서: 길이 → 구분자 → 부분별 종류 → 값의 범위',
review('🔁 1강 복습', [T('한 줄 표현의 문법을 확인해요.'), rev('`[x for x in a if x > 0]` 을 filter 로 쓰면?', code='list(filter(lambda x: x > 0, a))'), rev('앞에 쓰는 if 와 뒤에 쓰는 if 의 차이는?', '앞(if-else)은 값을 **고르고**, 뒤는 원소를 **걸러요**.'), rev('`zip` 은 길이가 다르면?', '짧은 쪽에 맞춰요.')]),
outq('복습 — 출력 결과는?', 'a = ["b", "a", "c"]\nprint([s * i for i, s in enumerate(a, 1) if s != "a"])\nprint(dict(zip(a, map(ord, a)))["c"] - 97)', review=True),
explain('split 과 join 의 세부 규칙',
  [T('`split` 은 인자가 있을 때와 없을 때 **빈 조각**을 다르게 다뤄요. 입력 파싱에서 자주 틀리는 곳이에요.'),
   C('s = "a  b   c"\nprint(s.split())        # 공백 덩어리를 하나로\nprint(s.split(" "))     # 공백 하나마다 자름 → 빈 문자열 생김\nprint("a,,b,".split(","))\nprint("2026-04-15".split("-"))\nprint("a b c d".split(" ", 2))   # 최대 2번만 자르기'),
   key('인자 없는 `split()` 은 앞뒤 공백도 무시해요. 구분자를 주면 **구분자 사이가 비어 있어도 빈 문자열 조각**이 생겨요.')],
  [T('`join` 은 split 의 반대예요. **문자열들만** 이을 수 있어요.'),
   cmp('오류 ❌', 'a = [1, 2, 3]\nprint("-".join(a))', '올바름 ✅', 'a = [1, 2, 3]\nprint("-".join(map(str, a)))\nprint("-".join(str(x) for x in a))', lb='TypeError — 원소가 문자열이 아님', tones=('bad', 'good')),
   C('words = "the quick brown fox".split()\nprint(" ".join(w.capitalize() for w in words))\nprint("".join(w[0] for w in words).upper())\nprint(" ".join(words[::-1]))', '단어 단위 가공: 첫 글자 대문자, 머리글자, 단어 순서 뒤집기')],
  [T('2023 문자열 문제(8점)는 메서드의 **결과 값**을 물었어요. 헷갈리는 것만 모았어요.'),
   flip(['"banana".count("ana")', '1 — 겹치지 않게 세요'], ['"banana".find("na", 3)', '4 — 3번 위치부터 찾아요'], ['"  hi  ".strip()', '"hi" — 양 끝 공백만 제거'], ['"a-b-c".replace("-", "", 1)', '"ab-c" — 한 번만 바꾸기'], ['"Hello".swapcase()', '"hELLO"'], ['"abc".isalpha(), "ab1".isalpha(), "".isalpha()', 'True, False, False'], ['"3.5".isdigit()', 'False — 점은 숫자가 아니에요'], ['"A1".isalnum(), "A 1".isalnum()', 'True, False'])]),
outq('[기출유사] 출력 결과는?', 's = "  Info,Science;I  "\nt = s.strip().replace(";", ",").split(",")\nprint(t, len(t))\nprint("/".join(x.lower()[:3] for x in t))\nprint(s.count(" "), s.find("S"), s.strip()[::-1].find("I"))'),
outq('[심화] 출력 결과는?', 'line = "kim@gsa.hs.kr"\nuid, dom = line.split("@")\nparts = dom.split(".")\nprint(uid, parts[-1], len(parts))\nprint(".".join(parts[1:]), "@".join([uid.upper(), parts[0]]))\nprint("a,b,,c".split(","), "a b  c".split(" "))'),
bucket('실행 결과를 나눠 보세요.', ['정상 실행', '오류'], [['"-".join(["a", "b"])', 1], ['"-".join([1, 2])', 2], ['"-".join("abc")', 1], ['"a b".split()[2]', 2], ['"abc".find("z")', 1], ['"abc".index("z")', 2], ['int("12 ".strip())', 1], ['"3,4".split(",") + 5', 2]], '`"-".join("abc")` 는 문자열도 글자의 나열이라 `"a-b-c"` 가 돼요.'),
explain('형식 검사 — 방송부 16점 유형',
  [T('2024 방송부 문제(16점): 이메일에서 아이디를 떼고, 비밀번호가 **8자 이상이며 문자와 숫자를 모두 포함**하는지 검사했어요. "모두 포함"은 **깃발 두 개**로 검사해요.'),
   trace('pw = "gsa2026!"\nhas_alpha = False\nhas_digit = False\nfor c in pw:\n    if c.isalpha():\n        has_alpha = True\n    elif c.isdigit():\n        has_digit = True\nok = len(pw) >= 8 and has_alpha and has_digit\nprint(has_alpha, has_digit, ok)', '글자마다 깃발을 세워요'),
   key('"하나라도 있는가"는 깃발을 False 로 시작해 발견하면 True. 한 줄로는 `any(c.isdigit() for c in pw)`.')],
  [T('`any` 와 `all` 로 쓰면 조건이 그대로 읽혀요.'),
   C('pw = "gsa2026!"\nprint(any(c.isdigit() for c in pw))      # 숫자가 하나라도\nprint(all(c.isalnum() for c in pw))      # 전부 글자·숫자인가\nprint(any(c.isupper() for c in pw))\nprint(sum(c.isdigit() for c in pw))      # 숫자의 개수'),
   flip(['any([])', 'False — 참인 것이 하나도 없음'], ['all([])', 'True — 거짓인 것이 하나도 없음'], ['"문자와 숫자를 모두 포함"', 'any(isalpha) and any(isdigit)'], ['"문자와 숫자로만 구성"', 'all(isalnum) — 뜻이 달라요!'])],
  [T('형식이 정해진 문자열은 **잘라서** 검사해요. 순서를 지키면 오류 없이 걸러져요.'),
   steps(['① 구분자로 자르기', '`a, b = s.split("@")` — 조각 수가 맞는지 먼저 (`s.count("@") == 1`)'], ['② 조각의 길이', '비어 있지 않은지, 범위 안인지'], ['③ 조각의 종류', '`isdigit()`, `isalpha()` …'], ['④ 값의 범위', '`int()` 로 바꾼 뒤 비교 — **③ 을 통과한 뒤에만** 안전']),
   warn('`a, b = s.split("@")` 는 `@` 가 없거나 두 개면 **ValueError**(값의 개수가 안 맞음)예요. 먼저 개수를 확인하세요.')]),
spot('[기출유사] 비밀번호 검사 코드예요. `"abcdefgh"`(숫자 없음)를 **통과시켜 버리는 버그**가 있는 줄은?', 'pw = input()\nok = False\nfor c in pw:\n    if c.isalpha() or c.isdigit():\n        ok = True\nif len(pw) >= 8 and ok:\n    print("사용 가능")\nelse:\n    print("사용 불가")', 4, '`or` 로 묶어 깃발 하나에 기록하면 "문자 **또는** 숫자가 있다"가 돼요. 문자용·숫자용 깃발을 따로 두고 `and` 로 확인해야 해요.'),
ch('[기출유사] "아이디는 영문자와 숫자**로만** 이루어져야 한다"를 바르게 검사한 것은?', ['`any(c.isalnum() for c in uid)`', '`uid.isalpha() and uid.isdigit()`', '`uid.isalnum()`', '`uid.isalpha() or uid.isdigit()`'], 3, '①은 하나만 맞아도 통과, ②는 동시에 참일 수 없고, ④는 "abc1" 처럼 섞인 경우를 거부해요.'),
explain('마스킹과 정렬 출력',
  [T('2023 스터디원 관리(20점)는 연락처를 **마스킹**해 출력했어요. 슬라이싱 + 반복 + join 의 조합이에요.'),
   C('tel = "010-1234-5678"\na, b, c = tel.split("-")\nprint(f"{a}-{b[0]}***-{c}")\nname = "남궁민수"\nprint(name[0] + "*" * (len(name) - 2) + name[-1])\nmail = "minsu@gsa.hs.kr"\nuid, dom = mail.split("@")\nprint(uid[:2] + "*" * (len(uid) - 2) + "@" + dom)'),
   tip('가리는 길이가 문자열마다 다르면 `"*" * (len(s) - 남길글자수)` 로 계산해요.')],
  [T('표 모양으로 출력하려면 f-string 의 **폭 지정**을 써요.'),
   C('rows = [("민", 80, 3.5), ("남궁솔", 100, 12.25)]\nfor n, s, t in rows:\n    print(f"[{n:<4}] [{s:>5}] [{t:6.2f}] [{s:05d}]")'),
   flip(['{x:<6}', '왼쪽 정렬, 폭 6'], ['{x:>6}', '오른쪽 정렬, 폭 6'], ['{x:^6}', '가운데 정렬'], ['{x:06.2f}', '소수 둘째 자리, 전체 폭 6, 빈칸은 0'], ['{x:,}', '천 단위 쉼표'], ['{x:.1%}', '백분율로 (0.256 → 25.6%)'])]),
fill('[기출유사] 이메일의 아이디를 앞 3글자만 남기고 `*` 로 가려요.', 'mail = "pynest2026@school.kr"\nuid, dom = mail.___("@")\nprint(uid[:3] + "*" * (___(uid) - 3) + "@" + dom)', ['split', 'len'], expect='pyn*******@school.kr'),
essay('[기출유사] 회원 가입 프로그램에서 "비밀번호는 8자 이상이고 영문자와 숫자를 모두 포함해야 한다"는 조건을 검사하려고 `if len(pw) >= 8 and pw.isalnum():` 이라고 썼어요. 이 코드의 **문제점 두 가지**를 예와 함께 서술하세요.', '(1) isalnum() 은 "모든 글자가 영문자 또는 숫자"인지를 검사할 뿐이므로, 영문자만 있는 "abcdefgh" 나 숫자만 있는 "12345678" 도 통과시킨다. 즉 "둘 다 포함"을 검사하지 못한다. (2) 반대로 "gsa2026!!" 처럼 특수문자가 들어 있으면 문자와 숫자를 모두 포함하고 있어도 isalnum() 이 False 가 되어 거부한다. 올바른 검사는 영문자가 하나라도 있는지와 숫자가 하나라도 있는지를 각각 확인하는 것이다(any(c.isalpha() …) and any(c.isdigit() …)).', ['isalnum 은 "로만 구성"을 검사한다고 썼다', '문자만/숫자만 있는 비밀번호가 통과된다는 예를 들었다', '특수문자가 섞이면 조건을 만족해도 거부된다고 썼다', '문자와 숫자를 각각 검사하는 올바른 방법을 썼다']),
prac('[기출유사] 방송부 회원 가입 심사', '방송부 가입 신청서가 `이메일 비밀번호` 형식으로 한 줄씩 주어져요.\n\n[조건]\n- 이메일에 `@` 가 정확히 하나 있어야 하고, 아이디(앞부분)는 4~10자의 영문 소문자·숫자여야 해요. 아니면 `이메일 오류`\n- 이미 가입된 아이디면 `중복 아이디`\n- 비밀번호는 8자 이상이고 영문자와 숫자를 **모두** 포함해야 해요. 아니면 `비밀번호 오류`\n- 비밀번호에 **아이디가 그대로 들어 있으면** `비밀번호 오류`\n- 통과하면 `가입 완료: 아이디` 를 출력하고 가입 처리\n- 검사는 위 순서대로 해요\n\n마지막 줄에 가입한 아이디를 **가입 순서대로** `, ` 로 이어 출력해요(없으면 `가입자 없음`).\n\n입력: 첫 줄 신청 수 `n`, 이어서 n줄',
  'n = int(input())\nmembers = []\nfor _ in range(n):\n    mail, pw = input().split()\n    ok = mail.count("@") == 1\n    if ok:\n        uid, dom = mail.split("@")\n        ok = 4 <= len(uid) <= 10 and all(c.islower() or c.isdigit() for c in uid)\n    if not ok:\n        print("이메일 오류")\n    elif uid in members:\n        print("중복 아이디")\n    elif len(pw) < 8 or not any(c.isalpha() for c in pw) or not any(c.isdigit() for c in pw) or uid in pw:\n        print("비밀번호 오류")\n    else:\n        members.append(uid)\n        print(f"가입 완료: {uid}")\nif members:\n    print(", ".join(members))\nelse:\n    print("가입자 없음")',
  ['5\nminsu@gsa.kr abcd1234\nminsu@naver.com qwer5678\nsol@gsa.kr abcd1234\njunho@@gsa.kr abcd1234\nhaneul@gsa.kr haneul2026', '1\nabcd@x.y 12345678', '2\nuser1@a.b pass1234\nUSER2@a.b pass1234', '3\naaaa@x.y abcdefg1\nbbbb@x.y abcdef1\ncccc@x.y abcdefgh', '2\nabcdefghijk@x.y aaaa1111\nab_c@x.y aaaa1111', '3\ntest@a.b zztest99zz\ntest@a.b qqqq1111\ntest@c.d qqqq2222'],
  hints=['`mail.count("@") == 1` 을 확인한 뒤에 `split("@")` 를 하세요.', '아이디: `all(c.islower() or c.isdigit() for c in uid)`', '비밀번호: `any(isalpha)` 와 `any(isdigit)` 를 따로, 그리고 `uid in pw`']),
prac('[기출유사] 타자 연습 리포트', '타자 연습 결과를 분석해요. 첫 줄에 제시문, 둘째 줄에 학생이 입력한 문장이 주어져요(단어는 공백 하나로 구분).\n\n- 첫 줄: **단어 단위**로 같은 위치끼리 비교해 맞은 단어 수와 제시문의 단어 수 `맞은수/전체`\n- 둘째 줄: 틀린 단어를 `제시문단어→입력단어` 형식으로 공백 구분 출력. 입력한 단어가 모자라 비교할 수 없는 위치는 `제시문단어→(없음)`. 모두 맞으면 `오타 없음`\n- 셋째 줄: 정확도(맞은 단어 수 ÷ 제시문 단어 수 × 100)를 소수 첫째 자리까지 `정확도 N%`\n\n입력한 단어가 제시문보다 많으면 넘치는 단어는 무시해요.\n\n[조건] ○ `split`, `zip`(또는 인덱스), `join` 을 사용할 것',
  'a = input().split()\nb = input().split()\nwrong = []\nok = 0\nfor i in range(len(a)):\n    if i < len(b):\n        if a[i] == b[i]:\n            ok += 1\n        else:\n            wrong.append(f"{a[i]}→{b[i]}")\n    else:\n        wrong.append(f"{a[i]}→(없음)")\nprint(f"{ok}/{len(a)}")\nif wrong:\n    print(" ".join(wrong))\nelse:\n    print("오타 없음")\nprint(f"정확도 {ok / len(a) * 100:.1f}%")',
  ['the quick brown fox\nthe quikc brown fax', 'hello\nhello', 'a b c\na b', 'one two three\none two three four', 'x y z\nz y x', 'python is fun\nPython is fun!'],
  hints=['두 문장을 `split()` 으로 단어 리스트로 만들어요.', '입력이 짧을 수 있으니 `zip` 만으로는 부족해요. 제시문의 인덱스로 돌면서 `i < len(b)` 를 확인하세요.', '`f"{ok / len(a) * 100:.1f}"`']),
prac('[심화] 로그 한 줄 해부', '서버 로그가 `[날짜 시각] 등급: 메시지 (key=value, key=value, …)` 형식으로 주어져요. 괄호 부분은 없을 수도 있어요.\n\n예: `[2026-04-15 09:30:05] ERROR: disk full (host=db1, used=98, mount=/data)`\n\n다음을 한 줄씩 출력하세요.\n1. 날짜를 `YYYY년 M월 D일` 로 (앞의 0 제거)\n2. 시각을 초로 환산한 값\n3. 등급을 소문자로\n4. 메시지(괄호 앞까지, 양 끝 공백 제거)\n5. key 들을 사전순으로 `key=value` 형식, `;` 로 구분 (괄호가 없으면 `-`)\n6. value 가 **숫자로만** 이루어진 항목들의 합 (없으면 0)\n\n[조건] ○ `find`/`split`/`strip`/슬라이싱을 조합해 해결할 것',
  's = input()\nclose = s.find("]")\ndate, time = s[1:close].split()\ny, m, d = map(int, date.split("-"))\nh, mi, se = map(int, time.split(":"))\nrest = s[close + 1:].strip()\ncolon = rest.find(":")\nlevel = rest[:colon]\nbody = rest[colon + 1:].strip()\npairs = []\nif body.endswith(")") and "(" in body:\n    op = body.rfind("(")\n    inner = body[op + 1:-1]\n    body = body[:op].strip()\n    pairs = [p.strip().split("=") for p in inner.split(",")]\nprint(f"{y}년 {m}월 {d}일")\nprint(h * 3600 + mi * 60 + se)\nprint(level.lower())\nprint(body)\nif pairs:\n    print(";".join(f"{k}={v}" for k, v in sorted(pairs)))\nelse:\n    print("-")\nprint(sum(int(v) for k, v in pairs if v.isdigit()))',
  ['[2026-04-15 09:30:05] ERROR: disk full (host=db1, used=98, mount=/data)', '[2026-01-01 00:00:00] INFO: server started', '[2025-12-31 23:59:59] Warn: retry: 3 times (n=3, wait=10)', '[2026-10-09 12:00:01] DEBUG: x (b=2,a=1)', '[2026-06-06 06:06:06] error: (code=500)', '[2026-11-30 01:02:03] INFO: user login ok (id=kim, ip=10.0.0.7, try=1, ms=250)'],
  hints=['`]` 의 위치를 `find` 로 찾아 앞뒤를 나눠요.', '등급은 **첫 번째** `:` 앞까지예요. 메시지 안에도 `:` 가 있을 수 있어요.', '괄호 부분: 마지막 `(` 를 `rfind` 로 찾고, 안쪽을 `,` 로 나눈 뒤 각 조각을 `=` 로 나눠요.'], ex='"구분자로 자르기 전에 **어느 구분자가 몇 번째인지**"를 정하는 것이 핵심이에요. 메시지에 `:` 가 또 나오므로 `split(":")` 로 통째로 자르면 안 돼요.'),
)

B3 = lesson('3강. 함수 설계 — 반환값·매개변수·변수의 범위', 45,
'- `return` 이 없거나 값 없이 끝나면 **None** — `print` 와 `return` 을 혼동하지 않기\n- 매개변수 순서: 일반 → 기본값 → `*args` → `**kwargs`\n- `*args` 는 **tuple**, `**kwargs` 는 **dict** 로 받는다\n- 기본값은 **함수를 정의할 때 한 번** 만들어진다 → 리스트 기본값은 공유됨 (`None` 을 쓰기)\n- 함수 안에서 대입하면 **지역 변수**. 전역을 바꾸려면 `global`\n- 리스트·딕셔너리를 넘기면 **같은 객체** — 메서드로 바꾸면 밖에서도 바뀐다',
review('🔁 1~2강 복습', [T('문자열 가공의 규칙을 확인해요.'), flip(['"a,,b".split(",")', '["a", "", "b"]'], ['"-".join([1, 2])', 'TypeError — 문자열만 이을 수 있음'], ['"문자와 숫자를 모두 포함" 검사', 'any(isalpha) and any(isdigit)'], ['all([])', 'True'])]),
outq('복습 — 출력 결과는?', 's = "id=kim;age=17;club="\nd = dict(p.split("=") for p in s.split(";"))\nprint(d["age"], repr(d["club"]), any(v.isdigit() for v in d.values()))', review=True),
explain('return 의 모든 것',
  [T('함수 문제에서 가장 많이 틀리는 것은 **print 와 return 의 혼동**이에요.'),
   cmp('print 만 하는 함수', 'def add(a, b):\n    print(a + b)\nx = add(2, 3)\nprint(x)', 'return 하는 함수', 'def add(a, b):\n    return a + b\nx = add(2, 3)\nprint(x)', lb='출력: 5 / None — 화면에 찍기만 하고 돌려주는 값이 없어요', rb='출력: 5', tones=('bad', 'good')),
   key('`return` 을 만나면 함수가 **즉시 끝나요**. return 이 없거나 `return` 만 쓰면 `None` 을 돌려줘요.')],
  [T('return 은 **반복문 안에서도** 함수를 끝내요. 위치가 한 칸만 달라도 결과가 달라져요.'),
   trace('def first_even(a):\n    for x in a:\n        if x % 2 == 0:\n            return x\n    return -1\nprint(first_even([3, 8, 6]))\nprint(first_even([1, 3]))', '찾으면 즉시 반환, 끝까지 못 찾으면 -1'),
   warn('`return -1` 을 for **안**(else 자리)에 쓰면 첫 원소가 홀수일 때 바로 -1 을 돌려줘요. "못 찾음"은 반복이 **다 끝난 뒤**에만 알 수 있어요.')],
  [T('여러 값을 돌려주면 **튜플**로 묶여요.'),
   C('def stats(a):\n    return min(a), max(a), sum(a) / len(a)\nr = stats([3, 9, 6])\nprint(r, type(r).__name__)\nlo, hi, avg = stats([3, 9, 6])\nprint(lo, hi, avg)'),
   exam('2026 3번(8점)은 기본값 인자 + 구간별 `return` 이었어요. if 마다 return 하면 elif 없이도 **위에서 걸러진** 효과가 나요.')]),
outq('[기출유사] 출력 결과는?', 'def fee(size, small=3500):\n    if size <= 2:\n        return small\n    if size <= 5:\n        return small + 1000\n    return small + 2500\nprint(fee(1), fee(5, 3000), fee(small=4000, size=9))'),
outq('[심화] 출력 결과는?', 'def f(a):\n    for x in a:\n        if x < 0:\n            return\n        print(x, end=" ")\n    return len(a)\nr1 = f([1, 2])\nr2 = f([3, -1, 4])\nprint()\nprint(r1, r2)'),
spot('[기출유사] 리스트에 음수가 **하나라도 있으면** True 를 돌려주려는 함수예요. 잘못된 줄은?', 'def has_negative(a):\n    for x in a:\n        if x < 0:\n            return True\n        else:\n            return False\nprint(has_negative([3, -1]))', 6, '첫 원소가 음수가 아니면 바로 False 를 돌려줘 버려요. `return False` 는 for 문이 끝난 뒤(바깥)에 있어야 해요.'),
explain('매개변수 — 기본값, *args, **kwargs',
  [T('2026 4번(11점)은 `*menus` 와 `**requests` 의 **자료형**과 `.items()` 를 물었어요.'),
   trace('def order(table, *menus, **requests):\n    print(type(menus).__name__, type(requests).__name__)\n    print(table, len(menus))\n    for k, v in requests.items():\n        print(k, v)\norder(7, "라면", "김밥", spicy=True, cup=2)', '*menus 는 tuple, **requests 는 dict'),
   key('위치 인자의 나머지는 `*args`(**튜플**)로, `이름=값` 인자의 나머지는 `**kwargs`(**딕셔너리**)로 모여요.')],
  [T('매개변수와 인자에는 **순서 규칙**이 있어요.'),
   flip(['def f(a, b=1, *args, **kw)', '올바른 순서: 일반 → 기본값 → *args → **kwargs'], ['def f(a=1, b)', 'SyntaxError — 기본값 뒤에 기본값 없는 매개변수 불가'], ['f(b=2, 1)', 'SyntaxError — 키워드 인자 뒤에 위치 인자 불가'], ['f(1, a=2) (def f(a, b))', 'TypeError — a 에 값이 두 번 들어감'], ['f(*[1, 2])', '리스트를 풀어 f(1, 2) 로 전달'], ['f(**{"a": 1, "b": 2})', '딕셔너리를 풀어 f(a=1, b=2) 로 전달']),
   C('def total(*nums, unit="원"):\n    return f"{sum(nums)}{unit}"\nprint(total(100, 200, 300))\nprint(total(*[1, 2, 3], unit="점"))\nprint(total())')],
  [T('**가변 기본값의 함정**: 기본값은 함수를 **정의할 때 딱 한 번** 만들어져요. 리스트를 기본값으로 쓰면 호출끼리 공유돼요.'),
   cmp('함정 ❌', 'def add(x, box=[]):\n    box.append(x)\n    return box\nprint(add(1))\nprint(add(2))', '올바름 ✅', 'def add(x, box=None):\n    if box is None:\n        box = []\n    box.append(x)\n    return box\nprint(add(1))\nprint(add(2))', lb='출력: [1] / [1, 2] — 같은 리스트가 계속 쓰여요', rb='출력: [1] / [2]', tones=('bad', 'good')),
   warn('기본값으로는 숫자·문자열·None 같은 **바뀌지 않는 값**만 쓰세요.')]),
outq('[기출유사] 출력 결과는?', 'def show(first, *rest, sep="-", **opt):\n    print(first, len(rest), sep, sorted(opt))\nshow(1)\nshow(1, 2, 3, sep="/")\nshow("a", "b", x=1, y=2)'),
outq('[심화] 출력 결과는?', 'def log(msg, hist=[]):\n    hist.append(msg)\n    return len(hist)\na = log("x")\nb = log("y", [])\nc = log("z")\nprint(a, b, c)', '기본 리스트를 쓰는 호출은 a 와 c 뿐이에요. b 는 새 리스트를 넘겼어요.'),
bucket('`def f(a, b=2, *c, **d): return a` 일 때 호출 결과를 나눠 보세요.', ['정상', '오류'], [['f(1)', 1], ['f()', 2], ['f(1, 2, 3, 4)', 1], ['f(1, a=5)', 2], ['f(b=3, a=1)', 1], ['f(1, x=9)', 1], ['f(*"ab")', 1], ['f(1, 2, b=3)', 2]], '`f(1, a=5)` 와 `f(1, 2, b=3)` 은 같은 매개변수에 값이 두 번 들어가 TypeError, `f()` 는 a 가 없어 TypeError.'),
explain('변수의 범위와 인자 전달',
  [T('함수 안에서 **대입**하면 그 이름은 함수 안에서만 사는 **지역 변수**가 돼요.'),
   cmp('전역을 못 바꿈', 'count = 0\ndef hit():\n    count = 1\nhit()\nprint(count)', 'global 로 바꿈', 'count = 0\ndef hit():\n    global count\n    count += 1\nhit()\nhit()\nprint(count)', lb='출력: 0 — 함수 안의 count 는 별개의 지역 변수', rb='출력: 2', tones=('', 'good')),
   warn('`global` 없이 `count += 1` 을 쓰면 **UnboundLocalError** 예요. 대입이 있으니 지역 변수로 보는데, 값을 읽으려니 아직 없어서요.')],
  [T('2026 9번(8점) 타일 재귀는 **호출 횟수를 global 변수**로 셌어요. 읽기만 할 때는 global 이 필요 없어요.'),
   C('RATE = 1.1\ncalls = 0\ndef price(x):\n    global calls\n    calls += 1\n    return int(x * RATE)     # RATE 는 읽기만 → global 불필요\nprint(price(1000), price(2000), calls)')],
  [T('리스트를 넘기면 **복사본이 아니라 같은 리스트**가 넘어가요. "바꾸기"와 "새로 대입하기"는 결과가 달라요.'),
   trace('def push(a):\n    a.append(9)\ndef reset(a):\n    a = []\n    a.append(1)\nx = [1, 2]\npush(x)\nreset(x)\nprint(x)', 'append 는 밖의 리스트를 바꾸고, a = [] 는 이름표만 옮겨요'),
   key('메서드로 **내용을 바꾸면** 밖에서도 보여요. `a = …` 로 **다시 대입하면** 그 순간부터 지역 변수가 다른 리스트를 가리킬 뿐이에요.')]),
outq('[기출유사] 출력 결과는?', 'total = 10\ndef a(x):\n    total = x * 2\n    return total\ndef b(x):\n    global total\n    total += x\n    return total\nprint(a(3), total, b(5), total)'),
sh('[심화] 아래 코드를 실행하면 발생하는 **오류의 이름**은?\n\n```\ncnt = 0\ndef up():\n    cnt = cnt + 1\nup()\n```', 'UnboundLocalError', '함수 안에 대입이 있어 cnt 는 지역 변수로 취급되는데, 오른쪽에서 그 값을 읽으려 할 때 아직 값이 없어요.', alts=['unboundlocalerror', 'UnboundLocalError 오류']),
essay('[기출유사] 아래 함수를 `add_item("펜")`, `add_item("자")` 순서로 호출하면 두 번째 결과가 `["펜", "자"]` 가 돼요. **이유**를 서술하고 **수정한 코드**를 쓰세요.\n\n```\ndef add_item(item, bag=[]):\n    bag.append(item)\n    return bag\n```', '매개변수의 기본값은 함수를 호출할 때마다 새로 만들어지는 것이 아니라 함수를 정의할 때 한 번만 만들어진다. 따라서 bag 의 기본값인 리스트는 하나뿐이고, 인자를 생략한 모든 호출이 이 같은 리스트를 함께 사용한다. 첫 호출에서 "펜"이 추가된 리스트에 두 번째 호출이 "자"를 또 추가하므로 ["펜", "자"] 가 된다. 수정: 기본값을 None 으로 두고 함수 안에서 `if bag is None: bag = []` 로 호출할 때마다 새 리스트를 만든다.', ['기본값은 정의할 때 한 번만 만들어진다고 썼다', '여러 호출이 같은 리스트를 공유한다고 썼다', '기본값을 None 으로 바꾼다고 썼다', '함수 안에서 새 리스트를 만든다고 썼다']),
prac('[기출유사] 택배 요금 함수', '택배 요금을 계산하는 함수 `fee(weight, base=3000, *options, **extra)` 를 설계해 요금을 출력하세요.\n\n[요금 규칙]\n- 무게 2kg 이하: base, 5kg 이하: base + 1500, 10kg 이하: base + 3500, 그 초과: base + 6000\n- 옵션(`*options`)마다 추가: `빠른` +2000, `파손주의` +1000, `냉장` +3000 (모르는 옵션은 무시)\n- 추가 요금(`**extra`): `이름=금액` 형태로 여러 개 올 수 있고 모두 더함\n\n입력: 한 줄에 `무게 [base=숫자] [옵션…] [이름=금액…]` 이 공백으로 주어져요. `base=` 로 시작하는 항목이 있으면 기본요금, `=` 가 들어간 나머지 항목은 추가 요금, 그 밖은 옵션이에요.\n\n출력: 첫 줄에 요금, 둘째 줄에 `옵션 N개, 추가 M개`\n\n[조건] ○ 함수 `fee` 를 정의하고 `*리스트`, `**딕셔너리` 로 인자를 풀어 호출할 것 ○ 무게 구간은 `return` 으로 처리할 것',
  'def weight_fee(w, base):\n    if w <= 2:\n        return base\n    if w <= 5:\n        return base + 1500\n    if w <= 10:\n        return base + 3500\n    return base + 6000\ndef fee(weight, base=3000, *options, **extra):\n    price = {"빠른": 2000, "파손주의": 1000, "냉장": 3000}\n    total = weight_fee(weight, base)\n    for o in options:\n        total += price.get(o, 0)\n    total += sum(extra.values())\n    return total\np = input().split()\nw = float(p[0])\nbase = 3000\nopts = []\nextra = {}\nfor x in p[1:]:\n    if x.startswith("base="):\n        base = int(x[5:])\n    elif "=" in x:\n        k, v = x.split("=")\n        extra[k] = int(v)\n    else:\n        opts.append(x)\nprint(fee(w, base, *opts, **extra))\nprint(f"옵션 {len(opts)}개, 추가 {len(extra)}개")',
  ['4.5 빠른 냉장 도서산간=4000', '2', '2.1 base=2500', '10 파손주의 선물포장 야간=1000 주말=500', '10.5 base=0', '5 빠른 빠른 빠른'],
  hints=['무게 구간 함수는 if 마다 `return` — elif 가 필요 없어요.', '모르는 옵션은 `price.get(o, 0)` 으로 0원 처리', '호출: `fee(w, base, *opts, **extra)`']),
prac('[기출유사] 호출 기록 장치', '계산기 함수들의 **호출 횟수**와 **결과 기록**을 관리하는 프로그램이에요.\n\n명령이 한 줄씩 주어지고 `끝` 에서 종료해요.\n- `add a b`, `sub a b`, `mul a b` : 계산 결과를 출력\n- `div a b` : 몫을 출력. b 가 0 이면 `0으로 나눌 수 없음` 을 출력(이 경우도 호출 횟수에는 포함, 결과 기록에는 미포함)\n- `count` : 지금까지 계산 함수가 호출된 총 횟수\n- `history` : 결과 기록을 공백으로 구분해 출력(없으면 `기록 없음`)\n- `undo` : 가장 최근 결과 기록 하나를 지우고 그 값을 출력(없으면 `기록 없음`)\n\n[조건] ○ 호출 횟수는 **전역 변수**를 `global` 로 갱신하는 함수로 셀 것 ○ 결과 기록 리스트는 함수에 **인자로 넘겨** 함수 안에서 `append` 할 것',
  'calls = 0\ndef calc(op, a, b, hist):\n    global calls\n    calls += 1\n    if op == "add":\n        r = a + b\n    elif op == "sub":\n        r = a - b\n    elif op == "mul":\n        r = a * b\n    else:\n        if b == 0:\n            return None\n        r = a // b\n    hist.append(r)\n    return r\nhistory = []\nwhile True:\n    p = input().split()\n    if p[0] == "끝":\n        break\n    if p[0] == "count":\n        print(calls)\n    elif p[0] == "history":\n        if history:\n            print(*history)\n        else:\n            print("기록 없음")\n    elif p[0] == "undo":\n        if history:\n            print(history.pop())\n        else:\n            print("기록 없음")\n    else:\n        r = calc(p[0], int(p[1]), int(p[2]), history)\n        if r is None:\n            print("0으로 나눌 수 없음")\n        else:\n            print(r)',
  ['add 3 4\nmul 2 5\ndiv 7 0\ncount\nhistory\nundo\nhistory\n끝', 'count\nhistory\nundo\n끝', 'sub 1 5\ndiv -7 2\nundo\nundo\nundo\ncount\n끝', 'div 0 5\nhistory\ncount\n끝', 'mul 0 0\nadd 0 0\nhistory\n끝', 'div 9 3\ndiv 9 0\ndiv 9 2\ncount\nhistory\n끝'],
  hints=['`global calls` 를 함수 첫 줄에 쓰고 `calls += 1`', '0 으로 나누는 경우는 `return None` — 호출한 쪽에서 `if r is None:` 으로 구분해요.', '`hist.append(r)` 는 밖의 리스트를 그대로 바꿔요.'], ex='결과가 0 일 수도 있으므로 실패를 `if not r:` 로 검사하면 안 돼요. **`is None`** 으로 구분해야 0 과 실패를 헷갈리지 않아요.'),
prac('[심화] 함수 조립 공장', '수열에 여러 변환을 **순서대로** 적용해요. 변환의 이름과 인자가 명령으로 주어져요.\n\n- `add k` : 모든 수에 k 를 더함\n- `mul k` : 모든 수에 k 를 곱함\n- `keep_even` : 짝수만 남김\n- `keep_gt k` : k 보다 큰 수만 남김\n- `rev` : 순서를 뒤집음\n- `uniq` : 중복 제거(처음 나온 것만 남기고 순서 유지)\n\n입력: 첫 줄에 수열, 둘째 줄에 명령 수 `q`, 이어서 q줄에 명령\n\n출력: 명령을 적용할 때마다 수열을 한 줄씩 출력(비면 `[]`). 수열이 비게 되면 그 줄까지만 출력하고 **남은 명령은 수행하지 않아요**.\n\n[조건] ○ 각 변환을 **함수**로 만들고, `이름 → 함수` 를 담은 **딕셔너리**에서 꺼내 호출할 것(if-elif 로 명령을 나누지 말 것) ○ 함수는 받은 리스트를 고치지 말고 **새 리스트를 반환**할 것',
  'def add(a, k):\n    return [x + k for x in a]\ndef mul(a, k):\n    return [x * k for x in a]\ndef keep_even(a):\n    return [x for x in a if x % 2 == 0]\ndef keep_gt(a, k):\n    return [x for x in a if x > k]\ndef rev(a):\n    return a[::-1]\ndef uniq(a):\n    out = []\n    for x in a:\n        if x not in out:\n            out.append(x)\n    return out\nfuncs = {"add": add, "mul": mul, "keep_even": keep_even, "keep_gt": keep_gt, "rev": rev, "uniq": uniq}\na = list(map(int, input().split()))\nfor _ in range(int(input())):\n    p = input().split()\n    args = list(map(int, p[1:]))\n    a = funcs[p[0]](a, *args)\n    if a:\n        print(*a)\n    else:\n        print("[]")\n        break',
  ['1 2 3 4\n3\nadd 1\nkeep_even\nrev', '5 5 5\n2\nuniq\nmul -2', '1 3 5\n3\nkeep_even\nadd 1\nrev', '3 1 2 3 1\n4\nrev\nuniq\nkeep_gt 1\nmul 10', '0\n2\nmul 0\nkeep_gt 0', '9 8 7\n1\nkeep_gt 100'],
  hints=['함수도 값이에요: `funcs = {"add": add, …}` 처럼 딕셔너리에 넣을 수 있어요.', '호출: `funcs[이름](a, *args)` — 인자가 없는 변환은 args 가 빈 리스트라 그대로 통해요.', '수열이 비면 `break`'], ex='`funcs[p[0]](a, *args)` 한 줄이 if-elif 여섯 갈래를 대신해요. α 응용편의 "조건을 리스트 인덱스로"와 같은 발상을 **함수**에 적용한 거예요.'),
)
